mkitem!{mkstruct!{# [doc = " Zero-Sized Type (ZST) for internal `BTreeSet` values."] # [doc = " Used instead of `()` to differentiate between:"] # [doc = " * `BTreeMap<T, ()>` (possible user-defined map)"] # [doc = " * `BTreeMap<T, SetValZST>` (internal set representation)"] # [derive (Debug , Eq , PartialEq , Ord , PartialOrd , Hash , Clone , Default)] pub (super) struct SetValZST ;}}
mkitem!{mktrait!{# [doc = " A trait to differentiate between `BTreeMap` and `BTreeSet` values."] # [doc = " Returns `true` only for type `SetValZST`, `false` for all other types (blanket implementation)."] # [doc = " `TypeId` requires a `'static` lifetime, use of this trait avoids that restriction."] # [doc = ""] # [doc = " [`TypeId`]: core::any::TypeId"] pub (super) trait IsSetVal { fn is_set_val () -> bool ; }}}
mkitem!{mkimpl!{impl < V > IsSetVal for V { default fn is_set_val () -> bool { false } }}}
mkitem!{mkimpl!{impl IsSetVal for SetValZST { fn is_set_val () -> bool { true } }}}